glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 grid = vec2(90.0 * uRatio, 90.0);
  vec2 id = floor(uv * grid);
  vec2 f = fract(uv * grid) - 0.5;
  float on = step(0.985, hash(id + floor(uTime * 6.0))) * step(0.55, luma(c.rgb));
  float star = max(0.0, 1.0 - abs(f.x) * 8.0) * max(0.0, 1.0 - abs(f.y) * 1.5)
             + max(0.0, 1.0 - abs(f.y) * 8.0) * max(0.0, 1.0 - abs(f.x) * 1.5);
  return vec4(c.rgb + vec3(star * on * 1.5 * uAmount), c.a);
}
